const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const expectedSecret = String($vars.N8N_WEBHOOK_SECRET || '').trim();
if (expectedSecret) {
  const provided = String(headers['x-cco-webhook-secret'] || headers['X-CCO-Webhook-Secret'] || '').trim();
  if (provided !== expectedSecret) throw new Error('Unauthorized webhook request.');
}
const attempt_id = String(body.attempt_id || '').trim();
const upload_id = String(body.upload_id || '').trim();
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuidRe.test(attempt_id)) throw new Error('Valid attempt_id is required.');
if (!uuidRe.test(upload_id)) throw new Error('Valid upload_id is required.');
return { json: { attempt_id, upload_id } };

const ctx = $('Load Marking Context RPC').item.json;
const bucket = ctx.upload?.storage_bucket;
const storagePath = ctx.upload?.storage_path;
if (!bucket) throw new Error('Storage bucket is missing.');
if (!storagePath) throw new Error('Storage path is missing.');
const encodedPath = String(storagePath).split('/').map(segment => encodeURIComponent(segment)).join('/');
const supabaseUrl = String($vars.SUPABASE_URL || '').replace(/\/$/, '');
if (!supabaseUrl) throw new Error('SUPABASE_URL n8n variable is missing.');
return {
  json: {
    download_url: `${supabaseUrl}/storage/v1/object/authenticated/${encodeURIComponent(bucket)}/${encodedPath}`,
    file_name: ctx.upload.original_file_name || 'answer.pdf',
    mime_type: ctx.upload.mime_type || 'application/pdf'
  }
};

const item = $input.item;
const binary = item.binary || {};
const keys = Object.keys(binary);
if (!keys.length) throw new Error('Supabase Storage did not return a PDF binary.');
const binaryKey = keys.includes('data') ? 'data' : keys[0];
const file = binary[binaryKey];
const mime = String(file.mimeType || 'application/pdf').toLowerCase();
const name = String(file.fileName || $('Build Storage Download').item.json.file_name || 'answer.pdf');
if (mime !== 'application/pdf' && !name.toLowerCase().endsWith('.pdf')) throw new Error(`Expected PDF, got ${mime || name}`);
return { json: { binary_property: binaryKey, file_name: name, mime_type: 'application/pdf' }, binary };

