parameters.jsCode:
const fileId = $json.id;
if (!fileId) throw new Error('OpenAI Files API did not return a file id.');

const ctx = $('Load Marking Context RPC').item.json;
const qs = ctx.written_questions || [];
if (!qs.length) throw new Error('No written questions found for this assessment.');

const expected = qs.map(q => ({
  question_id: q.id,
  question_number: q.question_number,
  question_text: q.question_text
}));

const prompt = `You are processing a student's handwritten examination answer PDF.

ASSESSMENT
${ctx.assessment.title}
Subject: ${ctx.assessment.subject_name}

EXPECTED WRITTEN QUESTIONS
${JSON.stringify(expected)}

PERFORM THESE TWO TASKS IN THIS SINGLE PDF READ.

TASK 1 — DOCUMENT QUALITY
Determine whether the PDF is reliable enough for automated handwriting transcription and marking.

Check:
- pages are visible and not badly cropped;
- orientation is readable;
- blur is not severe;
- lighting and contrast are sufficient;
- glare or shadows do not hide important writing;
- handwriting is readable enough to transcribe;
- question numbers or answer labels are reasonably identifiable.

Quality statuses:
GOOD = all or almost all important content is clearly readable.
ACCEPTABLE = minor issues exist, but answers can still be transcribed reliably.
REUPLOAD = important content is unreadable, cropped, missing, or too blurred for reliable marking.

TASK 2 — HANDWRITTEN ANSWER TRANSCRIPTION
Only if quality is GOOD or ACCEPTABLE, transcribe the student's answer for every expected written question.

Critical transcription rules:
- Transcribe what the student actually wrote.
- Do NOT solve the questions.
- Do NOT correct, improve, complete, paraphrase, or rewrite the student's answer.
- Use supplied question text only to match handwriting to the correct question.
- If no answer is present, status = blank and answer_text = "".
- If partly unclear, keep only readable content, status = low_confidence, and list unclear fragments.
- If it cannot be transcribed reliably, status = unreadable and do not guess.
- Return each expected question exactly once when quality is GOOD or ACCEPTABLE.
- page_numbers should identify where the answer appears when possible.
- If quality is REUPLOAD, return answers as an empty array. Do not waste tokens attempting a full transcription.

Never invent missing handwriting, missing pages, or student content.
Return only the required JSON schema.`;

const pageSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    page: { type: 'integer', minimum: 1 },
    status: { type: 'string', enum: ['GOOD', 'ACCEPTABLE', 'REUPLOAD'] },
    issues: { type: 'array', items: { type: 'string' } }
  },
  required: ['page', 'status', 'issues']
};

const answerSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    question_id: { type: 'string' },
    question_number: { type: 'string' },
    answer_text: { type: 'string' },
    confidence: { type: 'number', minimum: 0, maximum: 1 },
    status: { type: 'string', enum: ['readable', 'low_confidence', 'blank', 'unreadable'] },
    page_numbers: { type: 'array', items: { type: 'integer', minimum: 1 } },
    unclear_segments: { type: 'array', items: { type: 'string' } }
  },
  required: [
    'question_id',
    'question_number',
    'answer_text',
    'confidence',
    'status',
    'page_numbers',
    'unclear_segments'
  ]
};

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    quality: {
      type: 'object',
      additionalProperties: false,
      properties: {
        status: { type: 'string', enum: ['GOOD', 'ACCEPTABLE', 'REUPLOAD'] },
        can_process: { type: 'boolean' },
        page_count: { type: 'integer', minimum: 0 },
        all_pages_visible: { type: 'boolean' },
        handwriting_readable: { type: 'boolean' },
        issues: { type: 'array', items: { type: 'string' } },
        pages: { type: 'array', items: pageSchema },
        student_message: { type: 'string' }
      },
      required: [
        'status',
        'can_process',
        'page_count',
        'all_pages_visible',
        'handwriting_readable',
        'issues',
        'pages',
        'student_message'
      ]
    },
    answers: {
      type: 'array',
      minItems: 0,
      maxItems: qs.length,
      items: answerSchema
    }
  },
  required: ['quality', 'answers']
};

return {
  json: {
    openai_file_id: fileId,
    openai_body: {
      model: 'gpt-5.6-luna',
      store: false,
      reasoning: { effort: 'low' },
      max_output_tokens: 12000,
      input: [{
        role: 'user',
        content: [
          { type: 'input_text', text: prompt },
          { type: 'input_file', file_id: fileId }
        ]
      }],
      text: {
        format: {
          type: 'json_schema',
          name: 'answer_pdf_quality_and_transcription',
          strict: true,
          schema
        }
      }
    }
  }
};

const r = $json;

let text = '';
for (const out of (r.output || [])) {
  for (const c of (out.content || [])) {
    if (c.type === 'output_text' && c.text) text += c.text;
  }
}
if (!text) throw new Error('Combined PDF analysis returned no output_text.');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Invalid combined PDF-analysis JSON: ' + e.message);
}

const ctx = $('Load Marking Context RPC').item.json;
const q = parsed.quality || {};
q.can_process = q.can_process === true && q.status !== 'REUPLOAD';
q.db_quality_status =
  q.status === 'GOOD'
    ? 'good'
    : q.status === 'ACCEPTABLE'
      ? 'acceptable'
      : 'reupload_required';

let normalized = [];

if (q.can_process) {
  const returned = Array.isArray(parsed.answers) ? parsed.answers : [];
  const byId = new Map(returned.map(a => [String(a.question_id), a]));

  normalized = (ctx.written_questions || []).map(question => {
    const a = byId.get(String(question.id));

    if (!a) {
      return {
        question_id: question.id,
        question_number: question.question_number,
        answer_text: '',
        confidence: 0,
        status: 'unreadable',
        page_numbers: [],
        unclear_segments: ['No transcription returned for this expected question.']
      };
    }

    return {
      question_id: question.id,
      question_number: question.question_number,
      answer_text: String(a.answer_text || ''),
      confidence: Math.max(0, Math.min(1, Number(a.confidence || 0))),
      status: ['readable', 'low_confidence', 'blank', 'unreadable'].includes(a.status)
        ? a.status
        : 'low_confidence',
      page_numbers: Array.isArray(a.page_numbers) ? a.page_numbers : [],
      unclear_segments: Array.isArray(a.unclear_segments) ? a.unclear_segments : []
    };
  });
}

return {
  json: {
    quality: q,
    db_quality_status: q.db_quality_status,
    can_process: q.can_process,
    answers: normalized
  }
};

const ctx = $('Load Marking Context RPC').item.json;
const extracted = $('Parse Quality + Extracted Answers').item.json.answers || [];
const byId = new Map(extracted.map(a => [String(a.question_id), a]));

const all = (ctx.written_questions || []).map(q => {
  const a = byId.get(String(q.id)) || {};
  return {
    question_id: q.id,
    question_number: q.question_number,
    section: q.section || '',
    question_type: q.question_type,
    question_text: q.question_text,
    max_marks: Number(q.marks || 0),
    student_answer: String(a.answer_text || ''),
    extraction_confidence: Number(a.confidence || 0),
    extraction_status: a.status || 'unreadable',
    model_answer: q.model_answer,
    marking_scheme: q.marking_scheme
  };
});

// Group 1: short-answer / calculation style questions.
// Group 2: extended / essay / high-mark questions.
const shortGroup = [];
const extendedGroup = [];

for (const item of all) {
  const isExtended =
    String(item.section).toUpperCase() === 'C' ||
    ['essay', 'structured'].includes(String(item.question_type)) ||
    Number(item.max_marks) > 5;

  (isExtended ? extendedGroup : shortGroup).push(item);
}

const groups = [
  { name: 'short_and_calculation', items: shortGroup },
  { name: 'extended_and_essay', items: extendedGroup }
].filter(g => g.items.length > 0);

const resultItem = {
  type: 'object',
  additionalProperties: false,
  properties: {
    question_id: { type: 'string' },
    question_number: { type: 'string' },
    awarded_marks: { type: 'number', minimum: 0 },
    max_marks: { type: 'number', minimum: 0 },
    feedback: { type: 'string' },
    marking_confidence: { type: 'number', minimum: 0, maximum: 1 },
    needs_review: { type: 'boolean' },
    level_awarded: { type: 'string' },
    matched_marking_points: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          criterion: { type: 'string' },
          awarded_marks: { type: 'number', minimum: 0 }
        },
        required: ['criterion', 'awarded_marks']
      }
    }
  },
  required: [
    'question_id',
    'question_number',
    'awarded_marks',
    'max_marks',
    'feedback',
    'marking_confidence',
    'needs_review',
    'level_awarded',
    'matched_marking_points'
  ]
};

return groups.map(group => {
  const prompt = `You are an examination marker.

ASSESSMENT
${ctx.assessment.title}
Subject: ${ctx.assessment.subject_name}

MARKING GROUP
${group.name}

QUESTIONS, STUDENT TRANSCRIPTIONS, MODEL ANSWERS AND MARKING SCHEMES
${JSON.stringify(group.items)}

MARKING RULES
- Mark ONLY from the transcribed student_answer. The PDF is not available in this step.
- Apply each question's own stored marking_scheme and max_marks.
- Accept academically equivalent wording when it expresses the required meaning.
- Do not award knowledge the student did not actually write.
- Do not penalize spelling or grammar unless meaning is changed or explicitly assessed.
- For calculations, award method/workings marks only where supported by the marking scheme.
- For level-based essays, use the stored level_descriptors and indicative_content.
- blank = 0 marks and needs_review=false.
- unreadable = 0 provisional marks and needs_review=true.
- For low_confidence extraction, mark only readable content and set needs_review=true if uncertainty could change the score.
- awarded_marks must remain between 0 and max_marks.
- Give concise, useful feedback.
- Return every supplied question exactly once.
- Do not solve or alter the student's response beyond what is needed to apply the stored marking scheme.

Return only the required JSON schema.`;

  const schema = {
    type: 'object',
    additionalProperties: false,
    properties: {
      results: {
        type: 'array',
        minItems: group.items.length,
        maxItems: group.items.length,
        items: resultItem
      }
    },
    required: ['results']
  };

  return {
    json: {
      marking_group: group.name,
      openai_body: {
        model: 'gpt-5.6-luna',
        store: false,
        reasoning: { effort: 'low' },
        max_output_tokens: group.name === 'extended_and_essay' ? 9000 : 7000,
        input: [{
          role: 'user',
          content: [{ type: 'input_text', text: prompt }]
        }],
        text: {
          format: {
            type: 'json_schema',
            name: `written_marking_${group.name}`,
            strict: true,
            schema
          }
        }
      }
    }
  };
});

const responses = $input.all();

const combinedMarking = [];

for (const item of responses) {
  const r = item.json || {};
  let text = '';

  for (const out of (r.output || [])) {
    for (const c of (out.content || [])) {
      if (c.type === 'output_text' && c.text) text += c.text;
    }
  }

  if (!text) throw new Error('A grouped marking request returned no output_text.');

  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    throw new Error('Invalid grouped marking JSON: ' + e.message);
  }

  if (Array.isArray(parsed.results)) combinedMarking.push(...parsed.results);
}

const ctx = $('Load Marking Context RPC').item.json;
const extracted = $('Parse Quality + Extracted Answers').item.json.answers || [];

const exById = new Map(extracted.map(a => [String(a.question_id), a]));
const markById = new Map(combinedMarking.map(m => [String(m.question_id), m]));

const results = (ctx.written_questions || []).map(q => {
  const e = exById.get(String(q.id)) || {
    answer_text: '',
    confidence: 0,
    status: 'unreadable',
    page_numbers: [],
    unclear_segments: []
  };

  const m = markById.get(String(q.id)) || {};
  const max = Number(q.marks || 0);

  let awarded = Number(m.awarded_marks || 0);
  if (!Number.isFinite(awarded)) awarded = 0;
  awarded = Math.max(0, Math.min(max, awarded));

  let needsReview = Boolean(m.needs_review);

  if (e.status === 'blank') {
    awarded = 0;
    needsReview = false;
  }

  if (e.status === 'unreadable') {
    awarded = 0;
    needsReview = true;
  }

  if (e.status === 'low_confidence' && Number(e.confidence || 0) < 0.6) {
    needsReview = true;
  }

  return {
    question_id: q.id,
    question_number: q.question_number,
    extracted_answer: String(e.answer_text || ''),
    extraction_confidence: Math.max(0, Math.min(1, Number(e.confidence || 0))),
    extraction_status: e.status,
    page_numbers: Array.isArray(e.page_numbers) ? e.page_numbers : [],
    unclear_segments: Array.isArray(e.unclear_segments) ? e.unclear_segments : [],
    awarded_marks: awarded,
    max_marks: max,
    feedback: String(
      m.feedback ||
      (e.status === 'blank' ? 'No answer submitted.' : 'Answer requires review.')
    ),
    marking_confidence: Math.max(
      0,
      Math.min(1, Number(m.marking_confidence || 0))
    ),
    needs_review: needsReview,
    matched_marking_points: Array.isArray(m.matched_marking_points)
      ? m.matched_marking_points
      : [],
    level_awarded: String(m.level_awarded || '')
  };
});

// Hard validation: make sure every expected written question is represented once.
if (results.length !== (ctx.written_questions || []).length) {
  throw new Error(
    `Expected ${(ctx.written_questions || []).length} written results, got ${results.length}.`
  );
}

return [{ json: { results } }];

// Cost estimate uses current configured GPT-5.6 Luna rates. Update these constants if pricing changes.
const INPUT_RATE = 0.20;
const CACHED_INPUT_RATE = 0.02;
const CACHE_WRITE_RATE = 0.25;
const OUTPUT_RATE = 1.20;

const calls = [];
for (const item of $('OpenAI Analyze PDF Once').all()) calls.push({ stage: 'pdf_analysis', response: item.json });
$('OpenAI Mark 2 Text Groups').all().forEach((item, i) => calls.push({ stage: `marking_group_${i + 1}`, response: item.json }));

const breakdown = calls.map(call => {
  const response = call.response || {};
  const usage = response.usage || {};
  const inputTokens = Number(usage.input_tokens || 0);
  const cachedTokens = Number(usage.input_tokens_details?.cached_tokens || 0);
  const cacheWriteTokens = Number(usage.input_tokens_details?.cache_write_tokens || 0);
  const outputTokens = Number(usage.output_tokens || 0);
  const reasoningTokens = Number(usage.output_tokens_details?.reasoning_tokens || 0);
  const totalTokens = Number(usage.total_tokens || inputTokens + outputTokens);
  const normalInputTokens = Math.max(0, inputTokens - cachedTokens - cacheWriteTokens);
  const costUsd = (normalInputTokens / 1_000_000) * INPUT_RATE + (cachedTokens / 1_000_000) * CACHED_INPUT_RATE + (cacheWriteTokens / 1_000_000) * CACHE_WRITE_RATE + (outputTokens / 1_000_000) * OUTPUT_RATE;
  return { stage: call.stage, response_id: response.id || null, model: response.model || null, input_tokens: inputTokens, normal_input_tokens: normalInputTokens, cached_input_tokens: cachedTokens, cache_write_tokens: cacheWriteTokens, output_tokens: outputTokens, reasoning_tokens: reasoningTokens, total_tokens: totalTokens, cost_usd: Number(costUsd.toFixed(6)) };
});

const totals = breakdown.reduce((s,c) => ({ input_tokens:s.input_tokens+c.input_tokens, cached_input_tokens:s.cached_input_tokens+c.cached_input_tokens, cache_write_tokens:s.cache_write_tokens+c.cache_write_tokens, output_tokens:s.output_tokens+c.output_tokens, reasoning_tokens:s.reasoning_tokens+c.reasoning_tokens, total_tokens:s.total_tokens+c.total_tokens, cost_usd:s.cost_usd+c.cost_usd }), { input_tokens:0,cached_input_tokens:0,cache_write_tokens:0,output_tokens:0,reasoning_tokens:0,total_tokens:0,cost_usd:0 });
totals.cost_usd = Number(totals.cost_usd.toFixed(6));
return { json: { ...$json, ai_usage: { model: 'gpt-5.6-luna', api_calls: breakdown.length, ...totals, estimated_cost_usd: totals.cost_usd, breakdown } } };
